.seg button:first-child{border-radius:6px 0 0 6px}.seg button:last-child{border-radius:0 6px 6px 0}
.seg button+button{border-left:0}
.seg button[aria-pressed=true]{background:#1d3a8a;color:#fff;border-color:#1d3a8a}
.charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.chart{margin:0;min-width:0}
.chart figcaption{font-weight:600;margin-bottom:4px}
.chart svg{width:100%;height:auto;display:block}
.data-details{margin-top:12px}
.data-details summary{cursor:pointer;font-weight:600;padding:6px 0}
.table-wrap{overflow-x:auto;max-width:100%}
table{width:100%;border-collapse:collapse;font-size:.9rem}
th,td{padding:10px 8px;text-align:left;border-bottom:1px solid #e1e6ee;vertical-align:middle}
thead th{background:#eef1f6;font-weight:700}
tbody th{font-weight:500}
.num{text-align:right}
.name{overflow-wrap:anywhere}
.sort{background:none;border:0;font:inherit;font-weight:700;cursor:pointer;padding:4px;color:inherit}
.field{display:flex;align-items:center;gap:8px}
select{font:inherit;padding:8px;min-height:40px;border:1px solid #6b7686;border-radius:6px;background:#fff;color:#1a2230}
.badge{display:inline-block;padding:2px 10px;border-radius:999px;font-weight:600;font-size:.85rem;white-space:nowrap}
.badge.ok{background:#d9f2e1;color:#0b5a25}
.badge.degraded{background:#fdecc8;color:#6b4200}
.badge.down{background:#fbd9d9;color:#8a1111}
.alerts{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.alert{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;align-items:flex-start;border:1px solid #d5dbe3;border-radius:6px;padding:12px}
.alert>div{min-width:0;flex:1 1 240px}
.alert p{margin:4px 0 0;overflow-wrap:anywhere}
.acked .alert{background:#f3f5f9}
.sev{display:inline-block;padding:1px 8px;border-radius:4px;font-size:.8rem;font-weight:700}
.sev.critical{background:#8a1111;color:#fff}
.sev.warning{background:#fdecc8;color:#6b4200}
.sev.info{background:#dbe7fb;color:#173a80}
.btn{font:inherit;padding:8px 14px;min-height:40px;border:1px solid #1d3a8a;background:#fff;color:#1d3a8a;border-radius:6px;cursor:pointer;font-weight:600}
.btn.primary{background:#1d3a8a;color:#fff}
.state-box{background:#fff;border:1px solid #d5dbe3;border-radius:8px;padding:32px 20px;text-align:center}
.state-box h2{margin-bottom:8px}
.state-box p{margin:0 0 16px}
.loading-text{display:flex;align-items:center;justify-content:center;gap:10px;font-weight:600}
.spinner{width:18px;height:18px;border:3px solid #c3cbd8;border-top-color:#1d3a8a;border-radius:50%;animation:spin 1s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.spinner{animation:none}}
.skeleton-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:16px}
.skeleton{height:80px;background:#e6eaf1;border-radius:8px}
.skeleton.tall{height:200px}
@media (max-width:900px){
  .cards,.skeleton-cards{grid-template-columns:repeat(2,minmax(0,1fr))}
  .charts{grid-template-columns:minmax(0,1fr)}
}
@media (max-width:480px){
  main{padding:12px 8px 32px}
  .top{padding:12px}
  .cards{gap:8px}.card{padding:12px}
  .value{font-size:1.35rem}
  .panel{padding:12px}
  th,td{padding:8px 4px;font-size:.8rem}
  .badge{padding:2px 6px;font-size:.75rem}
}
